(function(){let b=[],si=-1,li=null,sn=28;
function gSrc(){const p=(typeof postPhotos!=="undefined"&&postPhotos[0])||null;if(p){const u=p.full||p.url||p.dataUrl||p.thumb||(typeof p==="string"?p:"");if(u)return u;}if(window._pendingRecogImage)return window._pendingRecogImage;for(const im of document.querySelectorAll("#post-modal img,#post-photo-preview img,#bundle-box img")){if(im.src&&!im.src.includes("guide-")&&!im.closest("#bundle-crop-host"))return im.src;}return "";}
function det(img,sens){const mw=400,sc=Math.min(1,mw/(img.naturalWidth||img.width||mw)),w=Math.max(40,Math.round((img.naturalWidth||img.width)*sc)),ht=Math.max(40,Math.round((img.naturalHeight||img.height)*sc)),c=document.createElement("canvas");c.width=w;c.height=ht;const x=c.getContext("2d");x.drawImage(img,0,0,w,ht);let d;try{d=x.getImageData(0,0,w,ht).data;}catch(e){return[{x:8,y:15,w:26,h:38,r:0},{x:37,y:15,w:26,h:38,r:0},{x:66,y:15,w:26,h:38,r:0}];}
const hist=new Map();let bestC=0,br=240,bg=240,bb=240;for(let y=1;y<ht-1;y+=2)for(let i=1;i<w-1;i+=2){const p=(y*w+i)*4,qr=d[p]>>4,qg=d[p+1]>>4,qb=d[p+2]>>4,k=qr+","+qg+","+qb,cnt=(hist.get(k)||0)+1;hist.set(k,cnt);if(cnt>bestC){bestC=cnt;br=qr*16+8;bg=qg*16+8;bb=qb*16+8;}}
const isWhiteBg=br>225&&bg>225&&bb>225,rawFg=new Uint8Array(w*ht),fg=new Uint8Array(w*ht),vs=new Uint8Array(w*ht),wCut=Math.min(249,Math.max(198,253-sens*0.7)),cTol=Math.max(12,(58-sens)*1.1),eTol=Math.max(10,(58-sens)*0.9);for(let y=2;y<ht-2;y++)for(let i=2;i<w-2;i++){const idx=y*w+i,p=idx*4,r=d[p],g=d[p+1],b=d[p+2];if(isWhiteBg){const lum=(r+g+b)/3,sat=Math.max(r,g,b)-Math.min(r,g,b);if(lum<wCut||sat>16)rawFg[idx]=1;}else{const pR=(idx+2)*4,pD=(idx+w*2)*4,df=Math.sqrt((r-br)**2+(g-bg)**2+(b-bb)**2)*0.62,gx=(Math.abs(r-d[pR])+Math.abs(g-d[pR+1])+Math.abs(b-d[pR+2]))/3,gy=(Math.abs(r-d[pD])+Math.abs(g-d[pD+1])+Math.abs(b-d[pD+2]))/3;if(df>cTol||gx>eTol||gy>eTol)rawFg[idx]=1;}}for(let y=2;y<ht-2;y++)for(let i=2;i<w-2;i++){const idx=y*w+i;let cnt=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(rawFg[(y+dy)*w+(i+dx)])cnt++;if(cnt>=4)fg[idx]=1;}
const out=[],qx=new Int32Array(w*ht),qy=new Int32Array(w*ht);for(let y=3;y<ht-3;y++)for(let i=3;i<w-3;i++){const idx=y*w+i;if(!fg[idx]||vs[idx])continue;let hd=0,tl=0;qx[tl]=i;qy[tl]=y;tl++;vs[idx]=1;let x0=i,x1=i,y0=y,y1=y,ar=0;while(hd<tl){const cx=qx[hd],cy=qy[hd];hd++;ar++;if(cx<x0)x0=cx;if(cx>x1)x1=cx;if(cy<y0)y0=cy;if(cy>y1)y1=cy;for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=cx+dx,ny=cy+dy;if(nx>2&&nx<w-3&&ny>2&&ny<ht-3){const ni=ny*w+nx;if(fg[ni]&&!vs[ni]){vs[ni]=1;qx[tl]=nx;qy[tl]=ny;tl++;}}}}const bw=x1-x0+1,bh=y1-y0+1,wp=(bw/w)*100,hp=(bh/ht)*100,fill=ar/(bw*bh);if(wp>=5&&hp>=6.5&&fill>=0.38){if(!isWhiteBg&&wp>35&&wp<=92&&hp<=70&&bh/bw<1.25){const cols=wp>62?3:2,cw=wp/cols;for(let k=0;k<cols;k++)out.push({x:+(x0/w*100+cw*k+0.5).toFixed(2),y:+(y0/ht*100).toFixed(2),w:+(cw-1).toFixed(2),h:+hp.toFixed(2),r:0});}else if(wp<=(isWhiteBg?34:48)&&hp<=(isWhiteBg?44:68)&&bh/bw>=0.55&&bh/bw<=2.35){out.push({x:+(x0/w*100).toFixed(2),y:+(y0/ht*100).toFixed(2),w:+wp.toFixed(2),h:+hp.toFixed(2),r:0});}}}if(out.length>=3){const sw=out.map(v=>v.w).sort((a,b)=>a-b)[Math.floor(out.length/2)],sh=out.map(v=>v.h).sort((a,b)=>a-b)[Math.floor(out.length/2)];out.forEach(v=>{if(Math.abs(v.w-sw)<sw*0.3){v.x=+(v.x+(v.w-sw)/2).toFixed(2);v.w=sw;}if(Math.abs(v.h-sh)<sh*0.3){v.y=+(v.y+(v.h-sh)/2).toFixed(2);v.h=sh;}});}out.sort((a,c)=>Math.abs(a.y-c.y)<7?a.x-c.x:a.y-c.y);return out.length?out:[{x:8,y:15,w:26,h:38,r:0},{x:37,y:15,w:26,h:38,r:0},{x:66,y:15,w:26,h:38,r:0}];}
function rnd(host,src){host.innerHTML=`<div id="inline-bulk-editor" class="bg-white border-2 border-purple-300 rounded-2xl p-3 space-y-2 shadow-md"><div class="bg-amber-50 border border-amber-200 rounded-xl px-2.5 py-2 text-[11px] text-amber-900 space-y-0.5"><div class="font-bold">📸 自動認識しやすくする撮影のコツ</div><div>・<b>無地の背景</b>（白・黒・単色の机など）の上で真上から撮る</div><div>・カード同士は<b>少し隙間を空けて</b>並べる</div><div>・スリーブの<b>光の反射や影</b>がかからないようにする</div></div><div class="flex justify-between text-xs font-bold text-purple-900"><span>🎯 ドラッグ移動・右下でサイズ調整(${b.length}枠)</span><span class="text-pink-600">バラバラOK</span></div><div class="flex items-center gap-2 bg-purple-50 px-2 py-1 rounded-xl"><span class="text-[11px] font-bold text-purple-800">感度</span><input id="ibs" type="range" min="5" max="55" value="${sn}" class="flex-1 accent-purple-600"/><button type="button" id="ibr" class="px-2 py-1 rounded bg-purple-600 text-white text-[11px] font-bold">再検出</button></div><div class="relative mx-auto w-fit max-w-full rounded-xl overflow-hidden border select-none touch-none bg-gray-900"><img src="${src}" class="block max-h-[50vh] w-auto object-contain pointer-events-none"/><div id="ibo" class="absolute inset-0"></div></div><div class="grid grid-cols-3 gap-1.5 text-xs font-bold"><button type="button" id="iba" class="py-2 rounded-xl bg-purple-100 text-purple-900">＋枠追加</button><button type="button" id="ibd" class="py-2 rounded-xl bg-rose-100 text-rose-700">選択解除</button><button type="button" id="ibc" class="py-2 rounded-xl bg-gradient-to-r from-purple-600 to-pink-500 text-white">✅ 枠確定</button></div></div>`;const ov=document.getElementById("ibo");ov.style.pointerEvents="auto";ov.addEventListener("click",e=>{if(e.target!==ov)return;const r=ov.getBoundingClientRect(),w=b.length?b[0].w:22,h2=b.length?b[0].h:32,x=Math.max(0,Math.min(100-w,+(((e.clientX-r.left)/r.width)*100-w/2).toFixed(2))),y=Math.max(0,Math.min(100-h2,+(((e.clientY-r.top)/r.height)*100-h2/2).toFixed(2)));b.push({x,y,w,h:h2,r:0});si=b.length-1;drw();});function drw(){ov.innerHTML="";b.forEach((v,i)=>{if(typeof v.r!=="number")v.r=0;const s=i===si,el=document.createElement("div");el.style.cssText=`position:absolute;left:${v.x}%;top:${v.y}%;width:${v.w}%;height:${v.h}%;transform:rotate(${v.r}deg);transform-origin:center center;border:2.5px solid ${s?"#ec4899":"#06b6d4"};background:${s?"rgba(236,72,153,.28)":"rgba(6,182,212,.18)"};border-radius:6px;touch-action:none;cursor:move;z-index:${s?20:10};`;el.innerHTML=`<span style="position:absolute;top:1px;left:2px;background:#000c;color:#fff;font-size:10px;font-weight:bold;padding:0 4px;border-radius:4px;pointer-events:none">#${i+1}</span><div data-rot="1" style="position:absolute;top:-22px;left:50%;transform:translateX(-50%);width:22px;height:22px;background:#3b82f6;border:2px solid #fff;border-radius:50%;touch-action:none;cursor:grab;box-shadow:0 2px 5px #0006;display:flex;align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:bold">↻</div><div data-r="1" style="position:absolute;right:-10px;bottom:-10px;width:24px;height:24px;background:#ec4899;border:2.5px solid #fff;border-radius:50%;touch-action:none;cursor:nwse-resize;box-shadow:0 2px 6px #0006"></div>`;let sx=0,sy=0,ox=v.x,oy=v.y,ow=v.w,oh=v.h,md=0,dg=false;const st=(cx,cy,tg)=>{si=i;md=(tg&&tg.dataset&&tg.dataset.rot==="1")?2:(tg&&tg.dataset&&tg.dataset.r==="1")?1:0;sx=cx;sy=cy;ox=v.x;oy=v.y;ow=v.w;oh=v.h;dg=true;ov.querySelectorAll("div[data-box]").forEach((d,k)=>{const a=k===i;d.style.borderColor=a?"#ec4899":"#06b6d4";d.style.background=a?"rgba(236,72,153,.28)":"rgba(6,182,212,.18)";d.style.zIndex=a?"20":"10";});};const mv=(cx,cy)=>{if(!dg)return;const r=ov.getBoundingClientRect();if(md===2){const bx=r.left+(v.x+v.w/2)/100*r.width,by=r.top+(v.y+v.h/2)/100*r.height;v.r=Math.round(Math.atan2(cy-by,cx-bx)*180/Math.PI+90);el.style.transform=`rotate(${v.r}deg)`;return;}const dx=((cx-sx)/r.width)*100,dy=((cy-sy)/r.height)*100;if(md===1){v.w=Math.max(4,Math.min(100-v.x,+(ow+dx).toFixed(2)));v.h=Math.max(4,Math.min(100-v.y,+(oh+dy).toFixed(2)));}else{v.x=Math.max(0,Math.min(100-v.w,+(ox+dx).toFixed(2)));v.y=Math.max(0,Math.min(100-v.h,+(oy+dy).toFixed(2)));}el.style.left=v.x+"%";el.style.top=v.y+"%";el.style.width=v.w+"%";el.style.height=v.h+"%";};el.dataset.box="1";el.addEventListener("touchstart",e=>{e.preventDefault();e.stopPropagation();const t=e.touches[0];st(t.clientX,t.clientY,e.target);},{passive:false});el.addEventListener("touchmove",e=>{e.preventDefault();e.stopPropagation();const t=e.touches[0];mv(t.clientX,t.clientY);},{passive:false});el.addEventListener("touchend",()=>{dg=false;});el.onpointerdown=e=>{if(e.pointerType==="touch")return;e.stopPropagation();st(e.clientX,e.clientY,e.target);el.setPointerCapture(e.pointerId);};el.onpointermove=e=>{if(e.pointerType==="touch"||!dg)return;mv(e.clientX,e.clientY);};el.onpointerup=()=>{dg=false;};ov.appendChild(el);});}drw();document.getElementById("ibs").oninput=e=>sn=+e.target.value;document.getElementById("ibr").onclick=()=>{if(li){b=det(li,sn);si=b.length?0:-1;rnd(host,src);}};document.getElementById("iba").onclick=()=>{b.push({x:15+(b.length*4)%40,y:15+(b.length*4)%40,w:22,h:32,r:0});si=b.length-1;rnd(host,src);};document.getElementById("ibd").onclick=()=>{if(si>=0&&b[si]){b.splice(si,1);si=b.length?0:-1;rnd(host,src);}else /* alert hidden */ console.log("解除したい枠を先にタップしてください");};document.getElementById("ibc").onclick=()=>{if(!b.length)return /* alert hidden */ console.log("1つ以上枠を設定してください");window.__isBulkMode=true;window.__bulkSlots=b.map((v,i)=>({id:"slot_"+(i+1),x:v.x,y:v.y,w:v.w,h:v.h,r:v.r||0,sold:false,tradeId:null}));const dt=document.getElementById("bundle-detect");if(dt)dt.innerHTML=`<span class="text-emerald-700 font-bold">✅ ${window.__bulkSlots.length}枠確定！下の「出品する」を押してください</span>`;host.innerHTML="";};}
window.openBundleFrameEditor=function(){const _b=(typeof window.isPostBundleMode==="function")?window.isPostBundleMode():(window.exchangeStyle==="single"?false:!!(window.exchangeStyle==="bundle"||window.__isBulkMode||window.isBulkMode||(document.getElementById("bulk-mode-panel")&&!document.getElementById("bulk-mode-panel").classList.contains("hidden"))));if(!_b){const _bx=document.getElementById("bundle-box");if(_bx)_bx.classList.add("hidden");const _h=document.getElementById("bundle-crop-host");if(_h)_h.innerHTML="";return;}const src=gSrc();if(!src){const _b2=document.getElementById("bundle-box");if(_b2)_b2.classList.remove("hidden");const _h=document.getElementById("bundle-crop-host");if(_h)_h.innerHTML='<p class="text-xs text-purple-700 font-bold py-2 text-center">写真を1枚入れると枠を自動検出します</p>';return;}const bx=document.getElementById("bundle-box");if(bx)bx.classList.remove("hidden");const host=document.getElementById("bundle-crop-host");if(!host)return;host.innerHTML="<p class=\"text-xs text-purple-700 font-bold py-2 text-center\">🔍 自動検出中...</p>";const im=new Image();im.crossOrigin="anonymous";im.onload=()=>{li=im;b=det(im,sn);si=b.length?0:-1;rnd(host,src);};im.onerror=()=>{b=[{x:10,y:10,w:35,h:45},{x:55,y:10,w:35,h:45}];si=0;rnd(host,src);};im.src=src;};let lastS="";setInterval(()=>{const bund=(typeof window.isPostBundleMode==="function")?window.isPostBundleMode():(window.exchangeStyle==="bundle");if(!bund){lastS="";return;}const s=gSrc();if(s&&s!==lastS){lastS=s;window.openBundleFrameEditor();}},600);})();
